-- Study topics: one plain-language topic per article, replacing Term / Region / New.
-- Bonus articles keep the category Bonus (shown as "Going Further"). Safe to run more than once.

UPDATE articles SET category = 'Tasting' WHERE category <> 'Bonus' AND title IN ('The Art of Wine Tasting', 'Judging whether a wine is any good', 'Naming what you smell', 'Body, alcohol and sweetness');
UPDATE articles SET category = 'Grapes & Regions' WHERE category <> 'Bonus' AND title IN ('Understanding Bordeaux', 'Tuscany & Sangiovese', 'The main white grapes', 'The main black grapes', 'Famous red wine names', 'Burgundy, Chardonnay and Beaujolais', 'Italy beyond Tuscany: Nebbiolo, Pinot Grigio and more', 'Riesling and German wine labels', 'Sauvignon Blanc, Chenin Blanc and the Alsace whites', 'The Rhône Valley: Syrah, Grenache and Viognier', 'Spain: Tempranillo, Rioja and Albariño', 'New World regions: Chile, Argentina, South Africa and Australia');
UPDATE articles SET category = 'How It''s Made' WHERE category <> 'Bonus' AND title IN ('Natural Wine Movement', 'How grapes grow and ripen', 'How red, white and rosé wines are made', 'Still, sparkling and fortified wines', 'Where grapes ripen: climate, slope and altitude', 'Winemaking choices: skins, oak, lees and blending', 'How sweet wines are made', 'How sparkling wine gets its bubbles', 'Fortified wines: Port and Sherry');
UPDATE articles SET category = 'Labels' WHERE category <> 'Bonus' AND title IN ('Reading a Pinot Noir label', 'Reading a Margaux label', 'Quality categories on European labels');
UPDATE articles SET category = 'At the Table' WHERE category <> 'Bonus' AND title IN ('Storing wine and keeping an open bottle fresh', 'Serving wine: temperature and opening', 'Food and wine: what changes in the glass', 'Bottle ageing, storage and wine faults', 'Serving temperature and food pairing');
